package com.transportlogistics.app.freight.manifest.adapters.outbound.persistence;
import com.transportlogistics.app.freight.manifest.ports.inbound.CargoManifestUseCase;import com.transportlogistics.app.freight.order.ports.inbound.FreightOrderUseCase;import com.transportlogistics.app.shared.domain.ConflictException;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.jdbc.core.JdbcTemplate;import java.math.BigDecimal;import java.time.OffsetDateTime;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest class CargoManifestPersistenceIntegrationTest {@Autowired CargoManifestUseCase manifests;@Autowired FreightOrderUseCase orders;@Autowired JdbcTemplate jdbc;UUID customer,origin,destination;
 @BeforeEach void seed(){customer=UUID.randomUUID();origin=UUID.randomUUID();destination=UUID.randomUUID();jdbc.update("INSERT INTO customer (id,code,name,active) VALUES (?,?,?,TRUE)",customer,"MC-"+shortId(customer),"Manifest Customer");jdbc.update("INSERT INTO location (id,code,name,active) VALUES (?,?,?,TRUE)",origin,"MO-"+shortId(origin),"Origin");jdbc.update("INSERT INTO location (id,code,name,active) VALUES (?,?,?,TRUE)",destination,"MD-"+shortId(destination),"Destination");}
 @AfterEach void clean(){jdbc.update("DELETE FROM cargo_manifest_item");jdbc.update("DELETE FROM cargo_manifest");jdbc.update("DELETE FROM freight_order_line");jdbc.update("DELETE FROM freight_order");jdbc.update("DELETE FROM location WHERE id IN (?,?)",origin,destination);jdbc.update("DELETE FROM customer WHERE id=?",customer);}
 @Test void roundTripsItemsPagingFinalizationAuditAndVersion(){var order=orders.create(new FreightOrderUseCase.CreateCommand(customer,origin,destination,OffsetDateTime.parse("2026-09-01T00:00:00Z"),OffsetDateTime.parse("2026-09-02T00:00:00Z"),"STANDARD","NORMAL",null,List.of(new FreightOrderUseCase.LineCommand(null,"Cargo",BigDecimal.TEN))),"creator");var manifest=manifests.create(new CargoManifestUseCase.CreateCommand(order.id()),"creator");var item=new CargoManifestUseCase.ItemCommand(manifest.version(),order.lines().getFirst().id(),"Cargo",BigDecimal.TEN,"Wrapped","SUPPLIER.CODE",false,null,false,null,null);var added=manifests.addItem(manifest.id(),item,"editor");assertEquals(1,added.items().size());assertEquals(1,added.version());assertTrue(manifests.validate(added.id()).ready());assertEquals(1,manifests.search(new CargoManifestUseCase.SearchQuery(added.manifestNumber(),order.id(),false,0,10,"manifestNumber","asc")).totalElements());var finalized=manifests.finalizeManifest(added.id(),added.version(),"finalizer");assertTrue(finalized.finalized());assertEquals("finalizer",finalized.finalizedBy());assertThrows(ConflictException.class,()->manifests.update(finalized.id(),new CargoManifestUseCase.UpdateCommand(finalized.version()),"editor"));}
 private String shortId(UUID id){return id.toString().substring(0,8);}}
